{
  "titre": "Les Trente Glorieuses : révision et entraînement",
  "objectifGeneral": "Réviser les principales caractéristiques des Trente Glorieuses grâce à des exercices interactifs et auto-correctifs.",
  "notionsPivots": [
    "la croissance économique",
    "les transformations sociales",
    "l'État-providence",
    "la société de consommation",
    "les inégalités",
    "la fin des Trente Glorieuses"
  ],
  "etapes": [
    {
      "titre": "Comprendre les repères chronologiques et les acteurs",
      "objectif": "Situer les Trente Glorieuses dans le temps et identifier leurs acteurs principaux",
      "cartes": [
        {
          "titre": "Frise des Trente Glorieuses",
          "objectif": "Placer les événements majeurs sur une frise chronologique",
          "module": "Timeline",
          "palier": "decouverte",
          "duree": 10,
          "consigne": "Consultez la frise chronologique et replacez les événements suivants dans l'ordre : début du baby-boom (1946), création de la Sécurité sociale (1945), premier choc pétrolier (1973), introduction du SMIG (1950)."
        }
      ]
    },
    {
      "titre": "S'entraîner sur les notions clés",
      "objectif": "Étudier et mémoriser le vocabulaire spécifique aux Trente Glorieuses",
      "cartes": [
        {
          "titre": "Cartes mémoires des Trente Glorieuses",
          "objectif": "Associer chaque concept à sa définition",
          "module": "Flashcards",
          "palier": "entrainement",
          "duree": 15,
          "consigne": "Utilisez les cartes mémoires pour apprendre les notions suivantes : croissance économique, État-providence, société de consommation, inégalités sociales, fin des Trente Glorieuses. Chaque carte propose un terme et une définition à associer correctement."
        }
      ]
    },
    {
      "titre": "Évaluer ses connaissances",
      "objectif": "Tester ses acquis sur les transformations sociales, économiques et les limites des Trente Glorieuses",
      "cartes": [
        {
          "titre": "Quiz sur les Trente Glorieuses",
          "objectif": "Répondre correctement à un QCM pour valider sa compréhension du cours",
          "module": "QuizSetQCM",
          "palier": "transfert",
          "duree": 15,
          "consigne": "Répondez au quiz qui porte sur les notions vues dans les étapes précédentes. Chaque question est suivie d'une rétroaction pour vous aider à comprendre vos erreurs."
        }
      ]
    },
    {
      "titre": "Synthétiser les acquis",
      "objectif": "Rédiger un texte de synthèse pour mobiliser les connaissances sur un aspect des Trente Glorieuses",
      "cartes": [
        {
          "titre": "Synthèse des Trente Glorieuses",
          "objectif": "Produire un texte structuré en utilisant les notions pivots",
          "module": "Essay",
          "palier": "transfert",
          "duree": 15,
          "consigne": "Rédigez un texte de 10 à 15 lignes expliquant une transformation majeure des Trente Glorieuses (ex : la croissance économique, l'État-providence, la société de consommation). Utilisez au moins 4 notions pivots parmi celles proposées."
        }
      ]
    }
  ]
}
